CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_UpdateSupply` (IN `p_id` INT, IN `p_name` VARCHAR(255), IN `p_category` VARCHAR(100), IN `p_unit` VARCHAR(50), IN `p_quantity` DECIMAL(10,2), IN `p_min_stock` DECIMAL(10,2), IN `p_notes` TEXT, IN `p_category_id` INT, IN `p_unit_id` INT)   BEGIN
