--
-- Triggers `menu`
--
DELIMITER $$
CREATE TRIGGER `tr_AfterMenuUpdate` AFTER UPDATE ON `menu` FOR EACH ROW BEGIN
    IF OLD.price <> NEW.price THEN
        CALL sp_LogSystemEvent(
            'security', 
            'Price Change', 
            'System',
            CONCAT('Item: ', NEW.name, ' | Price updated from ', OLD.price, ' to ', NEW.price),
            CONCAT('ID: ', NEW.id)
        );
    END IF;
    
    IF OLD.soldout <> NEW.soldout THEN
        CALL sp_LogSystemEvent(
            'activity', 
            'Stock Status', 
            'System',
            CONCAT('Item: ', NEW.name, ' | Status changed to ', IF(NEW.soldout, 'Sold Out', 'Available')),
            CONCAT('ID: ', NEW.id)
        );
    END IF;
END
$$
DELIMITER ;

