DELIMITER $$
CREATE TRIGGER `tr_AfterOrderUpdate` AFTER UPDATE ON `orders` FOR EACH ROW BEGIN
    IF OLD.status <> NEW.status THEN
        CALL sp_LogSystemEvent(
            'activity', 
            'Order Status', 
            'System',
            CONCAT('Order ', NEW.order_code, ' changed from ', OLD.status, ' to ', NEW.status),
            CONCAT('ID: ', NEW.id)
        );
    END IF;
END
$$
